modes.detail:
// ============ 为什么要单独定义 ElementType ============
//
// 排序算法本身和"排什么"没关系 —— 排整数、浮点数、字符串、
// 甚至排一个结构体数组，思路都完全一样。
//
// 所以把元素类型抽出来单独定义：
//
//     typedef int ElementType;
//
// 想排别的类型时改这一行就行。这是 C 语言里模拟"泛型"的常见做法
// （真要通用就用 void* 加函数指针，但那样代码会难读很多）。
//
// ============ Swap 为什么值得单独写 ============
//
// 三个算法里有两种"搬元素"的方式：
//
//   **交换**（冒泡）：A[j] 和 A[j+1] 互换，需要 3 次赋值（用临时变量）
//   **后移**（插入/希尔）：A[j-1] 覆盖 A[j]，只要 1 次赋值
//
// 这就是插入排序比冒泡快的原因之一：**移动次数少**。
// 冒泡每比较一次可能要交换（3 次赋值），插入每比较一次只要后移（1 次赋值）。
//
// 注意 Swap 的参数得是**指针** —— C 是按值传递的，传数组元素本身改不了。

// 待排序的元素类型（改这一行就能排别的类型）
typedef int ElementType;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 交换两个元素
// 参数是指针，因为 C 是值传递 —— 传值的话改的是副本。
void Swap(ElementType *a, ElementType *b)
{
// 用临时变量倒手
    ElementType t = *a;
    *a = *b;
    *b = t;
}

// 数组里的最小、最大元素（用来做边界判断）
ElementType MinOf(ElementType A[], int N)
{
// 循环用
    int i;
// 先假设第一个最小
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] < m)
        {
            m = A[i];
        }
    }
    return m;
}

// 数组里的最大元素
ElementType MaxOf(ElementType A[], int N)
{
// 循环用
    int i;
// 先假设第一个最大
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] > m)
        {
            m = A[i];
        }
    }
    return m;
}

