typedef int ElementType;

#define OK 1
#define ERROR 0
typedef int Status;

void Swap(ElementType *a, ElementType *b)
{
    ElementType t = *a;
    *a = *b;
    *b = t;
}

ElementType MinOf(ElementType A[], int N)
{
    int i;
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] < m)
        {
            m = A[i];
        }
    }
    return m;
}

ElementType MaxOf(ElementType A[], int N)
{
    int i;
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] > m)
        {
            m = A[i];
        }
    }
    return m;
}

/* ======== [已给出] 模块 03 InsertionSort ======== */

void InsertionSort(ElementType A[], int N)
{
    int i;
    int j;
    ElementType tmp;

    for (i = 1; i < N; i++)
    {
        tmp = A[i];

        for (j = i; j > 0 && A[j - 1] > tmp; j--)
        {
            A[j] = A[j - 1];
        }

        A[j] = tmp;
    }
}

/* ======== [已给出] 模块 05 PrintArray ======== */

void PrintArray(const ElementType A[], int N)
{
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

int IsSorted(const ElementType A[], int N)
{
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

int CountInversions(const ElementType A[], int N)
{
    int i, j;
    int count = 0;

    for (i = 0; i < N; i++)
    {
        for (j = i + 1; j < N; j++)
        {
            if (A[i] > A[j])
            {
                count++;
            }
        }
    }
    return count;
}

