// ============ 逆序对是什么 ============
//
// 一对下标 (i, j) 满足 i < j 但 A[i] > A[j]，就叫一个**逆序对**。
//
// 它衡量的是"这个数组离有序有多远"：
//
//   · 已经有序 → 逆序对 0
//   · 完全逆序 → 逆序对 n(n-1)/2（最多）
//
// 这个指标很实用：**插入排序的移动次数正好等于逆序对的个数**
// （每消除一个逆序对，就移动一次）。
//
// 所以用它可以直接验证插入排序有没有偷懒。

// 打印数组
void PrintArray(const ElementType A[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

// 检查数组是否从小到大有序
int IsSorted(const ElementType A[], int N)
{
// 循环用
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

// 数逆序对的个数
int CountInversions(const ElementType A[], int N)
{
// 双重循环
    int i, j;
// 计数
    int count = 0;

    for (i = 0; i < N; i++)
    {
        for (j = i + 1; j < N; j++)
        {
// 前面比后面大就是一个逆序对
            if (A[i] > A[j])
            {
                count++;
            }
        }
    }
    return count;
}

