/* ======== [已给出] 模块 01 typedef ======== */

typedef int ElementType;

#define OK 1
#define ERROR 0
typedef int Status;

void Swap(ElementType *a, ElementType *b)
{
    ElementType t = *a;
    *a = *b;
    *b = t;
}

ElementType MinOf(ElementType A[], int N)
{
    int i;
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] < m)
        {
            m = A[i];
        }
    }
    return m;
}

ElementType MaxOf(ElementType A[], int N)
{
    int i;
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] > m)
        {
            m = A[i];
        }
    }
    return m;
}

/* ======== [已给出] 模块 02 BubbleSort ======== */

void BubbleSort(ElementType A[], int N)
{
    int i;
    int j;
    int swapped;

    for (i = N - 1; i > 0; i--)
    {
        swapped = 0;

        for (j = 0; j < i; j++)
        {
            if (A[j] > A[j + 1])
            {
                Swap(&A[j], &A[j + 1]);
                swapped = 1;
            }
        }

        if (swapped == 0)
        {
            break;
        }
    }
}

/* ======== [已给出] 模块 03 InsertionSort ======== */

void InsertionSort(ElementType A[], int N)
{
    int i;
    int j;
    ElementType tmp;

    for (i = 1; i < N; i++)
    {
        tmp = A[i];

        for (j = i; j > 0 && A[j - 1] > tmp; j--)
        {
            A[j] = A[j - 1];
        }

        A[j] = tmp;
    }
}

/* ======== [已给出] 模块 04 ShellSort ======== */

void ShellSort(ElementType A[], int N)
{
    int d;
    int i, j;
    ElementType tmp;

    for (d = N / 2; d > 0; d /= 2)
    {
        for (i = d; i < N; i++)
        {
            tmp = A[i];

            for (j = i; j >= d && A[j - d] > tmp; j -= d)
            {
                A[j] = A[j - d];
            }

            A[j] = tmp;
        }
    }
}

/* ======== [已给出] 模块 05 PrintArray ======== */

void PrintArray(const ElementType A[], int N)
{
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

int IsSorted(const ElementType A[], int N)
{
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

int CountInversions(const ElementType A[], int N)
{
    int i, j;
    int count = 0;

    for (i = 0; i < N; i++)
    {
        for (j = i + 1; j < N; j++)
        {
            if (A[i] > A[j])
            {
                count++;
            }
        }
    }
    return count;
}

