#include <stdio.h>
#include <stdlib.h>

// ============ 为什么要单独定义 ElementType ============
//
// 排序算法本身和"排什么"没关系 —— 排整数、浮点数、字符串、
// 甚至排一个结构体数组，思路都完全一样。
//
// 所以把元素类型抽出来单独定义：
//
//     typedef int ElementType;
//
// 想排别的类型时改这一行就行。这是 C 语言里模拟"泛型"的常见做法
// （真要通用就用 void* 加函数指针，但那样代码会难读很多）。
//
// ============ Swap 为什么值得单独写 ============
//
// 三个算法里有两种"搬元素"的方式：
//
//   **交换**（冒泡）：A[j] 和 A[j+1] 互换，需要 3 次赋值（用临时变量）
//   **后移**（插入/希尔）：A[j-1] 覆盖 A[j]，只要 1 次赋值
//
// 这就是插入排序比冒泡快的原因之一：**移动次数少**。
// 冒泡每比较一次可能要交换（3 次赋值），插入每比较一次只要后移（1 次赋值）。
//
// 注意 Swap 的参数得是**指针** —— C 是按值传递的，传数组元素本身改不了。

// 待排序的元素类型（改这一行就能排别的类型）
typedef int ElementType;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 交换两个元素
// 参数是指针，因为 C 是值传递 —— 传值的话改的是副本。
void Swap(ElementType *a, ElementType *b)
{
// 用临时变量倒手
    ElementType t = *a;
    *a = *b;
    *b = t;
}

// 数组里的最小、最大元素（用来做边界判断）
ElementType MinOf(ElementType A[], int N)
{
// 循环用
    int i;
// 先假设第一个最小
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] < m)
        {
            m = A[i];
        }
    }
    return m;
}

// 数组里的最大元素
ElementType MaxOf(ElementType A[], int N)
{
// 循环用
    int i;
// 先假设第一个最大
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] > m)
        {
            m = A[i];
        }
    }
    return m;
}

// ============ 走一遍 ============
//
// 拿 { 5, 1, 4, 2, 8 } 举例：
//
// **第 1 轮**（范围是整个数组）：
//
//   5,1 → 换   1,5,4,2,8
//   5,4 → 换   1,4,5,2,8
//   5,2 → 换   1,4,2,5,8
//   5,8 → 不换 1,4,2,5,8      ← 8 到了末尾
//
// **第 2 轮**（范围缩到前 4 个）：
//
//   1,4 → 不换
//   4,2 → 换   1,2,4,5,8
//   4,5 → 不换                ← 5 到位
//
// **第 3 轮**（前 3 个）：1,2,4 已经有序，一次都不换
//
// ============ 三个关键点 ============
//
// **① 每轮之后，末尾多一个"已排好"的元素。**
//    因为每一轮都把当前范围内最大的那个一路换到了末尾。
//    所以内层循环的上界 `j < i` 里的 i 每轮减一 —— 已经排好的不用再看。
//
// **② flag 的作用：提前收工。**
//    如果某一轮从头到尾一次交换都没发生，说明数组已经有序，
//    再跑下去纯属浪费。这个优化让"已经有序"的输入变成 O(n) 而不是 O(n²)。
//
// **③ 冒泡是稳定的。**
//    因为只有 `A[j] > A[j+1]` 才交换，相等的不动 ——
//    所以相同元素的相对顺序不会变。
//    如果写成 `>=`，冒泡就变成不稳定的了，这一点要注意。
//
// ============ 复杂度 ============
//
// 比较次数：每轮 n-1、n-2、...、1，加起来约 n²/2，所以是 **O(n²)**。
//
// 交换次数最多也是 O(n²)，而每次交换要 3 次赋值，
// 所以冒泡在三个算法里通常是**最慢**的。

// 冒泡排序
void BubbleSort(ElementType A[], int N)
{
// 外层：i 是每轮的"右边界"
// 从 N-1 递减到 1。i 位置每轮都会变成当前范围内的最大值。
    int i;
// 内层：从前两个开始两两比较
    int j;
// 本趟有没有发生过交换
    int swapped;

    for (i = N - 1; i > 0; i--)
    {
// 每轮开始假设没交换过
        swapped = 0;

// 在 0..i 范围内两两比较
        for (j = 0; j < i; j++)
        {
// 前面比后面大就交换（注意这里是严格大于，保证稳定）
            if (A[j] > A[j + 1])
            {
                Swap(&A[j], &A[j + 1]);
// 记下发生过交换
                swapped = 1;
            }
        }

// 一趟下来一次都没换 → 已经有序，提前结束
// 这个优化让"本来就基本有序"的输入快很多 —— 最好情况 O(n)。
        if (swapped == 0)
        {
            break;
        }
    }
}

// ============ 就像打扑克摸牌 ============
//
// 想象你手里已经有一把排好的牌，现在新摸一张，你会：
//
//   · 从最右边开始往左看，比新牌大的就**往右挪一格**
//   · 挪到合适的位置，把新牌放进去
//
// 代码里就是这个意思：
//
//   把 A[i] 存进 tmp
//   从 i 往左看，比 tmp 大的都往右挪一格
//   最后把 tmp 放到空出来的位置
//
// ============ 走一遍 ============
//
// 拿 { 5, 1, 4, 2, 8 } 举例（| 左边是已排好的部分）：
//
//   5 | 1 4 2 8        把 1 插进去：5 后移，1 落在最前面
//   1 5 | 4 2 8        把 4 插进去：5 后移，4 落在 5 前面
//   1 4 5 | 2 8        把 2 插进去：5、4 后移，2 落在 4 前面
//   1 2 4 5 | 8        8 比 5 大，不用挪，直接留下
//   1 2 4 5 8 |
//
// ============ 为什么它比冒泡快 ============
//
// 关键在**移动的方式**：
//
//   冒泡：交换一次 = 3 次赋值（tmp 倒手）
//   插入：后移一次 = **1 次赋值**（A[j] = A[j-1]）
//
// 插入排序把元素**先取出来放在 tmp 里**，于是所有比它大的元素
// 只需要"往右挪一格"，不用两两交换。移动次数直接降到三分之一。
//
// 这就是"用一个临时变量换掉一堆交换"的思路，堆排序、快排里都会再用到。
//
// ============ 一个重要的性质：近乎有序时非常快 ============
//
// 插入排序的内层循环条件是 `A[j-1] > tmp`。
//
// 如果数组**本来就有序**，这个条件第一次就不成立，内层一次都不执行 ——
// 整体就是 **O(n)**，只需要 n-1 次比较。
//
// 这个性质非常宝贵：**希尔排序就是冲着它来的**（先用大步长把数组搞得
// 大致有序，再用插入排序收尾）。
//
// 而冒泡即使加了 flag，也还是要老老实实比较一轮才能发现有序。
//
// ============ 插入也是稳定的 ============
//
// 同样是严格大于才后移，相等的不动，所以稳定。

// 插入排序
void InsertionSort(ElementType A[], int N)
{
// 从第 2 个元素开始，逐个往前面已排好的部分里插
    int i;
// 内层：从 i 往左找位置
    int j;
// 暂存当前要插入的元素
// 一定要先存起来 —— 因为后面的"后移"会把它覆盖掉。
    ElementType tmp;

    for (i = 1; i < N; i++)
    {
// 把当前元素取出来
        tmp = A[i];

// 从 i 往左看：只要左边的比 tmp 大，就把它往右挪一格
// 循环结束时 j 就是 tmp 该待的位置。
        for (j = i; j > 0 && A[j - 1] > tmp; j--)
        {
// 后移一格 —— 只有 1 次赋值，比交换省
            A[j] = A[j - 1];
        }

// 落位
// 注意是放在循环**外面** —— 循环可能一次都没执行（元素本来就在对的位置）。
        A[j] = tmp;
    }
}

// ============ 为什么要改进插入排序 ============
//
// 插入排序有两个极端：
//
//   · 数组**基本有序** → 几乎不移动，O(n)，飞快
//   · 数组**完全逆序** → 每个元素都要挪到底，O(n²)，很慢
//
// 问题在于：逆序时，一个很小的元素待在很后面，插入排序只能**一格一格**地
// 把它挪到前面，太慢了。
//
// 希尔的想法很聪明：**我先不急着把它挪到位，先让它大步往左跳。**
//
// ============ 增量序列 ============
//
// 取一个步长 d，把下标相距 d 的元素看作一组，**组内做插入排序**：
//
//   d = 4 时，{ 5, 1, 4, 2, 8, 3 } 分成 4 组：
//
//      组1：(下标 0, 4)  →  5, 8
//      组2：(下标 1, 5)  →  1, 3
//      组3：(下标 2)     →  4
//      组4：(下标 3)     →  2
//
// 每组自己排好。然后 d 减半变成 2、再变成 1。
//
// **d = 1 的那一轮，就是普通的插入排序** —— 但此时数组已经"基本有序"了，
// 所以这一轮特别快。
//
// ============ 为什么这样就快了 ============
//
// 大步长的时候，一个远处的元素可以**一次跳过好几个位置**，
// 很快跑到大致该在的区域。
//
// 而每轮结束后，数组的"逆序程度"都在下降。到最后 d=1 时，
// 插入排序面对的是一个几乎有序的数组 —— 正是它最擅长的情况。
//
// 一句话：**用大步长快速消除"大尺度的乱"，用小步长收尾"小尺度的乱"。**
//
// ============ 复杂度 ============
//
// 希尔排序的复杂度**取决于增量序列怎么取**，分析起来很复杂。
//
//   折半序列（N/2, N/4, ..., 1）：大约 O(n²) 的最坏情况，但实际很快
//   Hibbard 序列（2^k - 1）    ：O(n^1.5)
//   Sedgewick 序列             ：O(n^1.3) 左右
//
// 这里用最简单的折半序列。它虽然不是理论最优，但代码短、效果明显。
//
// ============ 希尔排序是不稳定的 ============
//
// 因为分组的时候，两个相等的元素可能被分到不同的组里，
// 各自的移动路线不一样，**相对顺序可能被打乱**。
//
// 这是"分块处理"这类优化的通病 —— 快了，但丢了稳定性。

// 希尔排序（折半增量序列）
void ShellSort(ElementType A[], int N)
{
// 增量 d，从 N/2 开始每次减半
    int d;
// 组内插入排序用
    int i, j;
// 暂存当前元素
    ElementType tmp;

// 增量递减到 1 为止
// d = 1 那一轮就是普通插入排序 —— 但数组已经基本有序了。
    for (d = N / 2; d > 0; d /= 2)
    {
// 对每个组做插入排序
// i 从 d 开始，是因为每个组的前 d 个元素就是"已排好的部分"的起点。
        for (i = d; i < N; i++)
        {
// 取出当前元素
            tmp = A[i];

// 在**本组内**往前找位置：注意每次走 d 步，不是 1 步
// 这一行就是和普通插入排序唯一的区别：`j -= d` 而不是 `j--`，
// 比较的也是 A[j-d] 而不是 A[j-1]。
            for (j = i; j >= d && A[j - d] > tmp; j -= d)
            {
                A[j] = A[j - d];
            }

// 落位
            A[j] = tmp;
        }
    }
}

// ============ 逆序对是什么 ============
//
// 一对下标 (i, j) 满足 i < j 但 A[i] > A[j]，就叫一个**逆序对**。
//
// 它衡量的是"这个数组离有序有多远"：
//
//   · 已经有序 → 逆序对 0
//   · 完全逆序 → 逆序对 n(n-1)/2（最多）
//
// 这个指标很实用：**插入排序的移动次数正好等于逆序对的个数**
// （每消除一个逆序对，就移动一次）。
//
// 所以用它可以直接验证插入排序有没有偷懒。

// 打印数组
void PrintArray(const ElementType A[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

// 检查数组是否从小到大有序
int IsSorted(const ElementType A[], int N)
{
// 循环用
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

// 数逆序对的个数
int CountInversions(const ElementType A[], int N)
{
// 双重循环
    int i, j;
// 计数
    int count = 0;

    for (i = 0; i < N; i++)
    {
        for (j = i + 1; j < N; j++)
        {
// 前面比后面大就是一个逆序对
            if (A[i] > A[j])
            {
                count++;
            }
        }
    }
    return count;
}

// ============ 为什么要试两种数据 ============
//
// 只测随机数据，看不出这三个算法的差别 —— 都是 O(n²)，都很快跑完。
//
// 有意思的是**近乎有序**的数据：
//
//   · 插入排序会因为"基本有序"而飞快
//   · 冒泡即使有 flag，也要先扫一轮才能发现
//   · 希尔排序在大步长阶段就把乱的地方整得差不多了
//
// 所以下面用两组数据各跑一遍。

// 主函数
int main(void)
{
// 测试数据一：普通随机数据
    ElementType a1[] = { 5, 1, 4, 2, 8, 3, 9, 0, 7, 6 };
// 测试数据二：几乎有序（只有最后两个乱了）
    ElementType a2[] = { 0, 1, 2, 3, 4, 5, 6, 7, 9, 8 };
// 长度
    int n = 10;
// 三个工作副本
    ElementType b1[10], b2[10], b3[10];
// 循环用
    int i;
// 逆序对
    int inv;

// ===== 第一组 =====
    printf("=== 测试数据一（普通随机）===\n");
    printf("原始: ");
    PrintArray(a1, n);
    printf("\n逆序对 = %d（衡量离有序有多远）\n\n", CountInversions(a1, n));

// 冒泡
    for (i = 0; i < n; i++) b1[i] = a1[i];
    BubbleSort(b1, n);
    printf("冒泡排序: ");
    PrintArray(b1, n);
    printf("  %s\n", IsSorted(b1, n) ? "有序 ✓" : "还是乱的 ✗");

// 插入
    for (i = 0; i < n; i++) b2[i] = a1[i];
    InsertionSort(b2, n);
    printf("插入排序: ");
    PrintArray(b2, n);
    printf("  %s\n", IsSorted(b2, n) ? "有序 ✓" : "还是乱的 ✗");

// 希尔
    for (i = 0; i < n; i++) b3[i] = a1[i];
    ShellSort(b3, n);
    printf("希尔排序: ");
    PrintArray(b3, n);
    printf("  %s\n\n", IsSorted(b3, n) ? "有序 ✓" : "还是乱的 ✗");

// ===== 第二组 =====
    printf("=== 测试数据二（几乎有序，只有最后两个颠倒）===\n");
    printf("原始: ");
    PrintArray(a2, n);
    inv = CountInversions(a2, n);
    printf("\n逆序对 = %d（很少，说明已经很接近有序）\n\n", inv);

    for (i = 0; i < n; i++) b1[i] = a2[i];
    BubbleSort(b1, n);
    printf("冒泡排序: ");
    PrintArray(b1, n);
    printf("\n");

    for (i = 0; i < n; i++) b2[i] = a2[i];
    InsertionSort(b2, n);
    printf("插入排序: ");
    PrintArray(b2, n);
    printf("\n");

    for (i = 0; i < n; i++) b3[i] = a2[i];
    ShellSort(b3, n);
    printf("希尔排序: ");
    PrintArray(b3, n);
    printf("\n");

// 总结
    printf("\n三个算法都排对了，但思路一路在改进：\n");
    printf("  冒泡：相邻交换，每轮把最大的送到末尾\n");
    printf("  插入：维护有序前缀，用「后移」代替「交换」（移动次数降到 1/3）\n");
    printf("  希尔：大步长粗排 + 小步长收尾，利用「近乎有序时插入很快」这个性质\n");
    printf("\n只有插入排序的移动次数恰好等于逆序对数（%d 次）\n", inv);
    printf("（这是它「近乎有序就快」的根本原因）\n");

// 正常结束
    return 0;
}

