#include <stdio.h>
#include <stdlib.h>


// 待排序的元素类型（改这一行就能排别的类型）
typedef int ElementType;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 交换两个元素
void Swap(ElementType *a, ElementType *b)
{
// 用临时变量倒手
    ElementType t = *a;
    *a = *b;
    *b = t;
}

// 数组里的最小、最大元素（用来做边界判断）
ElementType MinOf(ElementType A[], int N)
{
// 循环用
    int i;
// 先假设第一个最小
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] < m)
        {
            m = A[i];
        }
    }
    return m;
}

// 数组里的最大元素
ElementType MaxOf(ElementType A[], int N)
{
// 循环用
    int i;
// 先假设第一个最大
    ElementType m = A[0];

    for (i = 1; i < N; i++)
    {
        if (A[i] > m)
        {
            m = A[i];
        }
    }
    return m;
}


// 冒泡排序
void BubbleSort(ElementType A[], int N)
{
// 外层：i 是每轮的"右边界"
    int i;
// 内层：从前两个开始两两比较
    int j;
// 本趟有没有发生过交换
    int swapped;

    for (i = N - 1; i > 0; i--)
    {
// 每轮开始假设没交换过
        swapped = 0;

// 在 0..i 范围内两两比较
        for (j = 0; j < i; j++)
        {
// 前面比后面大就交换（注意这里是严格大于，保证稳定）
            if (A[j] > A[j + 1])
            {
                Swap(&A[j], &A[j + 1]);
// 记下发生过交换
                swapped = 1;
            }
        }

// 一趟下来一次都没换 → 已经有序，提前结束
        if (swapped == 0)
        {
            break;
        }
    }
}


// 插入排序
void InsertionSort(ElementType A[], int N)
{
// 从第 2 个元素开始，逐个往前面已排好的部分里插
    int i;
// 内层：从 i 往左找位置
    int j;
// 暂存当前要插入的元素
    ElementType tmp;

    for (i = 1; i < N; i++)
    {
// 把当前元素取出来
        tmp = A[i];

// 从 i 往左看：只要左边的比 tmp 大，就把它往右挪一格
        for (j = i; j > 0 && A[j - 1] > tmp; j--)
        {
// 后移一格 —— 只有 1 次赋值，比交换省
            A[j] = A[j - 1];
        }

// 落位
        A[j] = tmp;
    }
}


// 希尔排序（折半增量序列）
void ShellSort(ElementType A[], int N)
{
// 增量 d，从 N/2 开始每次减半
    int d;
// 组内插入排序用
    int i, j;
// 暂存当前元素
    ElementType tmp;

// 增量递减到 1 为止
    for (d = N / 2; d > 0; d /= 2)
    {
// 对每个组做插入排序
        for (i = d; i < N; i++)
        {
// 取出当前元素
            tmp = A[i];

// 在**本组内**往前找位置：注意每次走 d 步，不是 1 步
            for (j = i; j >= d && A[j - d] > tmp; j -= d)
            {
                A[j] = A[j - d];
            }

// 落位
            A[j] = tmp;
        }
    }
}


// 打印数组
void PrintArray(const ElementType A[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

// 检查数组是否从小到大有序
int IsSorted(const ElementType A[], int N)
{
// 循环用
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

// 数逆序对的个数
int CountInversions(const ElementType A[], int N)
{
// 双重循环
    int i, j;
// 计数
    int count = 0;

    for (i = 0; i < N; i++)
    {
        for (j = i + 1; j < N; j++)
        {
// 前面比后面大就是一个逆序对
            if (A[i] > A[j])
            {
                count++;
            }
        }
    }
    return count;
}


// 主函数
